function glob(p){return new RegExp('^'+p.replace(/\./g,'\\.').replace(/\*/g,'.*').replace(/\?/g,'.')+'$');}
const g=glob('*.json');
console.log('*.json vs data.json:', g.test('data.json'), '| vs data.txt:', g.test('data.txt'));

function phash(px){const avg=px.reduce((s,v)=>s+v,0)/px.length;return px.map(v=>v>avg?1:0).join('');}
const a=[10,12,200,210],b=[11,13,199,211];
const ha=phash(a),hb=phash(b);
console.log('hash a:',ha,'hash b:',hb,'distance:',[...ha].filter((c,i)=>c!==hb[i]).length,'(near-dup)');

function fpHash(peaks){return peaks.map(p=>p.f+':'+p.t).join('|');}
const clip=[{f:440,t:0},{f:880,t:2}],song=[{f:440,t:10},{f:880,t:12}];
console.log('clip fp:',fpHash(clip));
console.log('relative offsets match:', clip[1].t-clip[0].t===song[1].t-song[0].t, '(time-offset invariant)');

const data={store:{book:[{title:'a',price:5},{title:'b',price:15}]}};
function jpath(o,p){return p.split('.').reduce((x,k)=>x&&x[k],o);}
const cheap=data.store.book.filter(b=>b.price<10);
console.log('books under 10:', cheap.map(b=>b.title), '| path walk:', jpath(data,'store.book').length,'books');

const sig=s=>s.toLowerCase().split('').sort().join('');
const words=['listen','silent','enlist','hello'];
const groups={};
words.forEach(w=>{(groups[sig(w)]=groups[sig(w)]||[]).push(w);});
console.log('anagram groups:',JSON.stringify(groups));

function subseq(p,t){let i=0;for(const c of t){if(c===p[i])i++;if(i===p.length)return true;}return false;}
const files=['foobar.js','foo-bar.ts','baz.js'];
console.log('query "fb" matches:',files.filter(f=>subseq('fb',f)));

function multiScan(text,pats){const hits=[];pats.forEach(p=>{let i=text.indexOf(p);while(i>=0){hits.push([p,i]);i=text.indexOf(p,i+1);}});return hits.sort((a,b)=>a[1]-b[1]);}
console.log(multiScan('the quick brown fox jumps', ['quick','fox','the']));
